mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
tok = None
log = open("/tmp/recon/http.log", "w")

def get_token():
    global tok
    while True:
        try:
            r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST", data=b""))
            tok = json.load(r)["token"]; log.write(f"TOKEN {tok}\n"); return
        except urllib.error.HTTPError as e:
            handle_err(e, "/token")

def handle_err(e, path):
    body = e.read().decode(errors="replace")
    log.write(f"{e.code} {path} hdrs={dict(e.headers)} body={body[:300]}\n"); log.flush()
    if e.code == 429:
        ra = e.headers.get("Retry-After")
        wait = float(ra) if ra else 1.0
        try:
            j = json.loads(body); wait = max(wait, float(j.get("retry_after", 0)))
        except Exception: pass
        time.sleep(wait + 0.05)
    elif e.code >= 500:
        time.sleep(0.5)
    return body

def get(path):
    global tok
    if tok is None: get_token()
    for attempt in range(200):
        req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {tok}"})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            raw = r.read().decode()
            log.write(f"200 {path}\n")
            return 200, json.loads(raw)
        except urllib.error.HTTPError as e:
            body = handle_err(e, path)
            if e.code == 401: get_token()
            elif e.code == 404: return 404, body
            elif e.code in (429,) or e.code >= 500: pass
            else:
                time.sleep(0.5)
        except (urllib.error.URLError, json.JSONDecodeError, ConnectionError, TimeoutError) as e:
            log.write(f"EXC {path} {e!r}\n"); time.sleep(0.5)
    raise RuntimeError("gave up " + path)

pages = {}
path = "/orders?page=1"
while path:
    code, d = get(path)
    pages[d["page"]] = d
    print("page", d["page"], d["total_pages"], len(d["items"]), d["next"], file=sys.stderr)
    path = d["next"]
json.dump(pages, open("/tmp/recon/pages.json", "w"))
# also verify every page 1..total_pages was fetched
tp = pages[1]["total_pages"]
missing = [p for p in range(1, tp + 1) if p not in pages]
print("missing pages", missing, file=sys.stderr)
for p in missing:
    code, d = get(f"/orders?page={p}"); pages[p] = d
json.dump(pages, open("/tmp/recon/pages.json", "w"))

cids = sorted({o["customer_id"] for p in pages.values() for o in p["items"]})
custs = {}
for c in cids:
    code, d = get(f"/customers/{c}")
    custs[c] = d if code == 200 else {"_status": code, "_body": d}
json.dump(custs, open("/tmp/recon/customers.json", "w"))
print("customers", len(custs), file=sys.stderr)
EOF
cd /tmp/recon && python3 -I fetch.py 2>&1 | tail -40; grep -v '^200' http.log | cut -c1-300 | sort | uniq -c | sort -rn | head -30

